import numpy as np
from scipy.linalg import solve
from scipy.optimize import minimize_scalar


def _polys(x, degree):
    return np.column_stack([np.ones(len(x))]+[np.prod(x[:, k], axis=1) for d in range(1, degree+1) for k in combinations_with_replacement(range(4), d)])


def _fold_profile(z, t):
    def profile(k):
        return -np.expm1(-k*t)

    def err(k):
        q = profile(k)
        return np.linalg.norm(z-np.outer(z@q/(q@q), q))

    return profile(minimize_scalar(err, bounds=(.1, 2), method='bounded').x)


def _cubic_readout(b, v, n, lam):
    F = np.c_[_polys(b, 2), np.tanh(3.0*_polys(b, 3)[:, 15:])/3.0]
    A = F[:n]; center = A.mean(0); scale = np.maximum(.25, A.std(0))
    A = (A-center)/scale; G = (F[n:]-center)/scale
    m = v.mean()
    return G@A.T@solve(A@A.T+lam*np.eye(n), v-m, assume_a='pos')+m


def _scalar_readout(b, y, n):
    P = _polys(b, 3); C = P[:, 15:]
    F = np.c_[P[:, :15], C/(1+0.6*C*C)]
    A = F[:n]; scale = np.maximum(.25, A.std(0)); G = (F-A.mean(0))/scale; T = G[:n]
    c = max(abs(y))*1.3; v = c*np.arctanh(y/c)
    mean = v.mean()
    z = G[n:]@T.T@solve(T@T.T+0.045*np.eye(n), v-mean, assume_a='pos')+mean
    return c*np.tanh(z/c)


def run_node(inputs: dict) -> dict:
    s = inputs['node_00']; n = s['n']
    q = _fold_profile(s['traj'], s['times'])
    Y = np.c_[s['y'], s['traj']@q/(q@q)]
    # Preserve the source's first ridge fit, whose output is not used.
    _cubic_readout(s['b_lin'], Y[:, 0], n, 0.02)
    amplitude = _cubic_readout(s['b_cube'], Y[:, 1], n, 0.08)
    y = _scalar_readout(s['b_scalar'], s['y'], n)
    z = np.outer(amplitude, q)
    return {'y_hat': y, 'state_pred': z, 'diagnostics_vec': np.array([y.mean(), y.std(), z[:, -1].mean(), z[:, -1].std()])}
